report=fileread(fullfile(docs,'PHASE5_FINAL_REPORT.md'));
report=strrep(strrep(strrep(report,'&','&amp;'),'<','&lt;'),'>','&gt;');
put(fullfile(docs,'manual','phase5_protection_manual.html'),{['<!doctype html><meta charset="utf-8"><title>Phase 5 final engineering study</title><style>body{max-width:1100px;margin:2em auto;font:15px/1.5 system-ui}pre{white-space:pre-wrap}</style><pre>' report '</pre>']});
 function write(name,lines)
  put(fullfile(docs,name),lines); copyfile(fullfile(docs,name),fullfile(root,name));
 end
end
function b=bullets(c)
b=cellfun(@(x)['- ' x],reshape(c,1,[]),'UniformOutput',false);
end
function put(path,lines)
fid=fopen(path,'w','n','UTF-8'); assert(fid>=0,'phase5b_reports:write','Cannot write %s',path);
cleanup=onCleanup(@()fclose(fid)); %#ok<NASGU>
for i=1:numel(lines), fprintf(fid,'%s\n',lines{i}); end
end
